1	package relayproof
2	
3	import (
4		"errors"
5		"strings"
6		"testing"
7	)
8	
9	// Regression guard for "wait first, then judged replay" inside one advance:
10	// submitting first does not win the nonce. Two messages share
11	// (source, destination, nonce) but differ in proof height; only the one whose
12	// proof height is covered by the trusted header consumes the combination. The
13	// first-submitted message is processed first and goes waiting (proof height
14	// 101 > trusted 100), the second succeeds (proof height 100 <= trusted 100),
15	// and the phase-2 replay sweep then terminalizes the first message in the
16	// same advance — its freshly scheduled backoff must not shield it.
17	//
18	// The report therefore lists the first message twice (waiting, then replay);
19	// both entries are existing behavior and must be kept.
20	func TestWaitingThenReplaySameAdvance(t *testing.T) {
21		q, _ := openTempQueue(t)
22		defer q.Close()
23		if err := q.RegisterSource("a"); err != nil {
24			t.Fatal(err)
25		}
26		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
27			t.Fatal(err)
28		}
29		// Same (from, to, nonce); different ids and proof heights. Neither
30		// expires (ExpiresAt 0).
31		if _, err := q.Submit(env("early", "a", "b", 7, 101, 0)); err != nil {
32			t.Fatal(err)
33		}
34		if _, err := q.Submit(env("later", "a", "b", 7, 100, 0)); err != nil {
35			t.Fatal(err)
36		}
37	
38		rep, err := q.Advance(1000)
39		if err != nil {
40			t.Fatal(err)
41		}
42		if rep.Now != 1000 {
43			t.Fatalf("report time: want 1000, got %d", rep.Now)
44		}
45		want := []Result{
46			{ID: "early", Status: StatusWaiting, Reason: "waiting for trusted header covering height 101 (current 100)"},
47			{ID: "later", Status: StatusSuccess, Reason: "delivered; proof verified by trusted header at height 100"},
48			{ID: "early", Status: StatusReplay, Reason: "nonce combination already consumed by message later"},
49		}
50		if len(rep.Results) != len(want) {
51			t.Fatalf("want %d results (early appears twice: waiting then replay), got %+v", len(want), rep.Results)
52		}
53		for i, w := range want {
54			if rep.Results[i] != w {
55				t.Fatalf("result %d: want %+v, got %+v", i, w, rep.Results[i])
56			}
57		}
58	
59		// The waiting-then-replayed message: two attempts (the waiting processing
60		// and the replay terminalization), retry schedule cleared, reason naming
61		// the message that actually succeeded.
62		if r := statusOf(t, q, "early"); r.Status != StatusReplay ||
63			r.Attempts != 2 || r.NextRetry != 0 ||
64			!strings.Contains(r.Reason, "later") {
65			t.Fatalf("early must be replay with 2 attempts and no retry, got %+v", r)
66		}
67		// The covered message succeeded on its first attempt and owns the nonce.
68		if r := statusOf(t, q, "later"); r.Status != StatusSuccess || r.Attempts != 1 || r.NextRetry != 0 {
69			t.Fatalf("later must be success with 1 attempt, got %+v", r)
70		}
71		if winner := q.consumed[newConsumeToken("a", "b", 7)]; winner != "later" {
72			t.Fatalf("nonce consumption must belong to later, got %q", winner)
73		}
74	}
75	
76	// Boundary of the same rule: when the trusted header covers neither proof
77	// height, both messages stay waiting with one attempt each — sharing a nonce
78	// alone never turns either into a replay.
79	func TestSharedNonceBothWaitingWhenHeaderInsufficient(t *testing.T) {
80		q, _ := openTempQueue(t)
81		defer q.Close()
82		if err := q.RegisterSource("a"); err != nil {
83			t.Fatal(err)
84		}
85		// Trusted height 99 covers neither proof height 101 nor 100.
86		if err := q.UpsertHeader(Header{Chain: "a", Height: 99, Root: "0x99", Trusted: true}); err != nil {
87			t.Fatal(err)
88		}
89		if _, err := q.Submit(env("early", "a", "b", 7, 101, 0)); err != nil {
90			t.Fatal(err)
91		}
92		if _, err := q.Submit(env("later", "a", "b", 7, 100, 0)); err != nil {
93			t.Fatal(err)
94		}
95	
96		rep, err := q.Advance(1000)
97		if err != nil {
98			t.Fatal(err)
99		}
100		if len(rep.Results) != 2 {
101			t.Fatalf("want exactly 2 waiting results, got %+v", rep.Results)
102		}
103		for _, res := range rep.Results {
104			if res.Status != StatusWaiting {
105				t.Fatalf("no message may be replayed for a shared nonce alone: %+v", rep.Results)
106			}
107		}
108		for _, id := range []string{"early", "later"} {
109			if r := statusOf(t, q, id); r.Status != StatusWaiting || r.Attempts != 1 || r.NextRetry != 2000 {
110				t.Fatalf("%s must stay waiting with 1 attempt and retry at 2000, got %+v", id, r)
111			}
112		}
113		if _, taken := q.consumed[newConsumeToken("a", "b", 7)]; taken {
114			t.Fatal("no delivery happened; the nonce must remain unconsumed")
115		}
116	}
117	
118	// Save failure inside the same operation: the first message's waiting result
119	// and the second message's success result are already saved when persisting
120	// the first message's replay result fails. The advance must surface the
121	// storage error; the unsaved replay must not leak into queries (the first
122	// message keeps its committed waiting state, reason, single attempt and the
123	// 2000ms retry instant), the committed success and its nonce consumption must
124	// not be rolled back, and the instance refuses further writes.
125	func TestWaitingThenReplaySaveFailureKeepsCommittedState(t *testing.T) {
126		q, _ := openTempQueue(t)
127		defer q.Close()
128		if err := q.RegisterSource("a"); err != nil {
129			t.Fatal(err)
130		}
131		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
132			t.Fatal(err)
133		}
134		if _, err := q.Submit(env("early", "a", "b", 7, 101, 0)); err != nil {
135			t.Fatal(err)
136		}
137		if _, err := q.Submit(env("later", "a", "b", 7, 100, 0)); err != nil {
138			t.Fatal(err)
139		}
140	
141		// Appends so far: source(1), header(2), submit early(3), submit later(4).
142		// Within the advance: early's waiting result is call 5 (committed),
143		// later's success is call 6 (committed), early's replay is call 7: fail.
144		q.store.injectErr = errors.New("disk on fire")
145		q.store.injectErrOnCall = 7
146	
147		_, err := q.Advance(1000)
148		if !errors.Is(err, ErrStorage) {
149			t.Fatalf("want ErrStorage from the failed replay save, got %v", err)
150		}
151		if !strings.Contains(err.Error(), "terminalize") {
152			t.Fatalf("error must keep the terminalize op label, got %v", err)
153		}
154	
155		// The unsaved replay is not published: early keeps its previously
156		// committed waiting result, waiting reason, one attempt and the retry
157		// instant at 2000ms scheduled during that wait.
158		if r := statusOf(t, q, "early"); r.Status != StatusWaiting ||
159			r.Reason != "waiting for trusted header covering height 101 (current 100)" ||
160			r.Attempts != 1 || r.NextRetry != 2000 {
161			t.Fatalf("early must keep its committed waiting state, got %+v", r)
162		}
163		// The committed success is not revoked and still owns the nonce.
164		if r := statusOf(t, q, "later"); r.Status != StatusSuccess || r.Attempts != 1 {
165			t.Fatalf("committed later success must survive the later failure: %+v", r)
166		}
