174		// Queries remain usable on the broken instance, but every further write
175		// is refused.
176		if got, ok := q.Query("early"); !ok || got.Status != StatusWaiting {
177			t.Fatalf("query after failure must still show committed waiting: %+v ok=%v", got, ok)
178		}
