180			t.Fatalf("broken queue must refuse writes, got %v", err)
181		}
182		if _, err := q.Submit(env("m3", "a", "b", 8, 100, 0)); !errors.Is(err, ErrStorage) {
183			t.Fatalf("broken queue must refuse submits, got %v", err)
184		}
185		if err := q.UpsertHeader(Header{Chain: "a", Height: 200, Trusted: true}); !errors.Is(err, ErrStorage) {
186			t.Fatalf("broken queue must refuse header writes, got %v", err)
187		}
